[472] = { en = "Fall of Dun Modr", tier = 2,
  t = "De val van Dun Modr",
  d = "Dun Modr is gevallen voor de Dark Iron Dwarves!$b$bMijn wonden zijn ernstig, $c. Bijna het hele regiment is gedood! De boeven van de Dark Irons vielen ons aan voordat we na de hinderlaag bij de Thandol Span weer bij elkaar konden komen.$b$bOnze leider, Longbraid, blies op de hoorn voor de terugtocht. Toen we de stad verlieten, kreeg ik een verdwaalde bijl in mijn rug. Alles werd zwart.$b$bIk werd hier in Menethil wakker, maar ik ben bang voor mijn medesoldaten. Er brandt nog steeds hoop in mij. Misschien leeft Longbraid nog! Kijk of je hem kunt vinden bij Dun Modr, $r!",
  o = "Zoek Longbraid bij het stadje Dun Modr.",
  c = "Welke dappere $C stuurt bericht uit Menethil? Ah, $N noemen ze je.$b$bJe brengt hoop in een hopeloze situatie. Het is echt goed nieuws dat de jonge Harlo het heeft overleefd. Toen hij vluchtte, raakte hij zwaar gewond. We hadden maar weinig tijd om hem weg te sturen, op de rug van het enige paard van het regiment dat nog leefde.$b$bMaar nu zitten we in een gevaarlijke situatie. Dun Modr is gevallen, en we zijn nog maar een schaduw van het grote regiment dat we vroeger waren.",
  g = { {"wonden", "wounds (wond)"}, {"ernstig", "serious, grave"}, {"boeven", "thugs, villains (boef)"}, {"hinderlaag", "ambush"}, {"terugtocht", "retreat"}, {"verdwaalde", "stray (verdwaald)"}, {"bijl", "axe"}, {"medesoldaten", "fellow soldiers (medesoldaat)"}, {"hopeloze", "hopeless (hopeloos)"}, {"overleefd", "survived (overleven)"}, {"vluchtte", "fled (vluchten)"}, {"gewond", "wounded"}, {"schaduw", "shadow"} },
},

[275] = { en = "Blisters on The Land", tier = 2,
  t = "Blaren op het land",
  d = "Ik weet niet waarom, maar er groeit een ontsteking in de Wetlands. De Fen Creepers zijn opgestaan. Ze zijn zieke blaren vol koorts op het land. Om de koorts te laten zakken, moeten ze gedood worden. Dan kunnen ze weer wegzakken in de moerassen.$B$BDe Fen Creepers sloffen rond tussen de waterwegen van de Wetlands.",
  o = "Dood 12 Fen Creepers en ga dan terug naar Rethiel the Greenwarden in de Wetlands.",
  p = "De Wetlands huilen nog steeds, en de Fen Creepers zijn nog steeds woedend. Kom terug als je taak klaar is.",
  c = "Door jouw inzet is dit land tot rust gekomen. Daarom schenk ik je een gunst.",
  g = { {"blaren", "blisters (blaar)"}, {"ontsteking", "infection, festering"}, {"opgestaan", "risen (opstaan)"}, {"koorts", "fever"}, {"laten zakken", "to bring down (fever)"}, {"wegzakken", "to sink away"}, {"moerassen", "marshes (moeras)"}, {"sloffen", "shamble, shuffle (sloffen)"}, {"waterwegen", "waterways (waterweg)"}, {"woedend", "furious, raging"}, {"inzet", "effort, dedication"}, {"schenk", "grant, give (schenken)"}, {"gunst", "favour, boon"} },
},

[471] = { en = "Apprentice's Duties", tier = 2,
  t = "De taken van de leerling",
  d = "Ik stuurde mijn leerling de moerassen in. Hij moest een paar van onze beroemde reuzenkrokolisken van de Wetlands villen. Toen hij niet terugkwam, ging ik hem zoeken... Laten we zeggen dat het geen mooi gezicht was.$b$bDe vroedvrouw zegt dat hij het misschien haalt, maar intussen heb ik nog steeds mijn huiden nodig!$b$b...Als je nog een paar van die beesten wilt doden, heb ik daar niets op tegen, na wat ze gedaan hebben. Je vindt de krokolisken in het noorden langs de kust, voorbij de hutjes van de murlocs.",
  o = "Verzamel 6 Giant Crocolisk Skins en breng ze naar James Halloran in Menethil Harbor.",
  p = "Mijn leerling is als een zoon voor mij. Het wordt moeilijk voor hem om te leven met maar één been.$b$bAh, $N, hoe gaat het? Heb je mijn huiden?",
  c = "Hmm... Je hebt zeker geen zin om mijn leerling te worden?$b$bHa! Nee, ik maak maar een grapje. Om te beginnen ben je veel te oud. En trouwens, zo te zien heb je andere doelen in het leven. Toch zijn dit mooie huiden die je hebt gehaald, en ik kan ze goed gebruiken.",
  g = { {"leerling", "apprentice, student"}, {"beroemde", "famous (beroemd)"}, {"villen", "to skin"}, {"geen mooi gezicht", "not a pretty sight"}, {"vroedvrouw", "midwife"}, {"het misschien haalt", "might pull through (halen)"}, {"intussen", "in the meantime"}, {"huiden", "skins, hides (huid)"}, {"heb ik daar niets op tegen", "I wouldn't be opposed"}, {"hutjes", "hovels, little huts (hutje)"}, {"grapje", "joke"}, {"trouwens", "besides, by the way"}, {"zo te zien", "from the looks of it"} },
},

[288] = { en = "The Third Fleet", tier = 2,
  t = "De Derde Vloot",
  d = "Ik was ooit eerste stuurman op de Wave Mistress, een linieschip van de Derde Vloot van Kul Tiras. De Gedoemde Vloot. Gedoemd, want op haar laatste reis werd de vloot aangevallen door rode draken. Draken die bestuurd werden door orcs!$B$BWe maakten geen kans tegen dat drakenvuur... en onze vloot werd verbrand en zonk hier voor de kust. Ik ben de enige overlevende van die arme schepen...$B$B...Oh, mijn hoofd bonkt en dreunt! Ik heb een vers drankje nodig als ik deze kater de baas wil worden en mijn verhaal wil afmaken.",
  o = "Koop een Flagon of Mead voor First Mate Fitzsimmons.",
  p = "Oh, ik heb zo'n dorst! Wil je niet een drankje kopen voor deze arme, zielige dwaas?",
  c = "Ah! Dat doet goed, en het maakt de tong los. Bedankt, maat!",
  g = { {"vloot", "fleet"}, {"stuurman", "mate (on a ship)"}, {"linieschip", "ship of the line"}, {"gedoemd", "doomed"}, {"bestuurd", "controlled, steered (besturen)"}, {"zonk", "sank (zinken)"}, {"overlevende", "survivor"}, {"bonkt", "pounds (bonken)"}, {"dreunt", "hammers, booms (dreunen)"}, {"kater", "hangover"}, {"de baas wil worden", "want to get a handle on (de baas worden)"}, {"zielige", "pathetic (zielig)"}, {"dwaas", "fool"}, {"maakt de tong los", "loosens the tongue"} },
},

[295] = { en = "Ormer's Revenge", tier = 2,
  t = "De wraak van Ormer",
  d = "Nu is het tijd om die vreselijke raptors echt spijt te laten krijgen van hun bloeddorst. Hier beneden zijn heel veel Mottled Scytheclaws en Mottled Razormaws. Laat die rotbeesten boeten: dood er van elk 10!",
  o = "Ormer Ironbraid wil dat je 10 raptors van de soort Mottled Scytheclaw en 10 van de soort Mottled Razormaw doodt. Ga daarna terug naar hem bij de Whelgar Excavation Site.",
