[299] = { en = "Uncovering the Past", tier = 2,
  t = "Het verleden opgraven",
  d = "Vlak voor de invasie vond ik een grote stenen tafel, de Goaz Stone. De vertaalde tekst breekt op 4 plaatsen af. De tekst spreekt over een \"goddelijk plan\" en een \"gedoemde profetie\".$b$bIk ben bang dat we bijna geen tijd meer hebben. Ik ben te oud om naar beneden te gaan en die beesten te trotseren. Maar jij bent sterk.$b$bDoorzoek de opgravingsplek en vind de 4 ontbrekende stukken van de stenen tafel: Ados, Modr, Golm en Neru. Zoek ernaar in oude voorwerpen of waar de grond los is. Breng ze naar mij, dan kan ik beginnen het mysterie op te lossen!",
  o = "Prospector Whelgar wil dat je de opgravingsplek doorzoekt naar de 4 ontbrekende stukken van de stenen tafel: Ados, Modr, Golm en Neru.",
  p = "Heb je de vier stukken al gevonden, $N? Ados, Modr, Golm en Neru...",
  c = "Ah, de Goaz Stone is compleet! Goed werk, $N. Echt heel goed werk. Nu kan ik verder met de lastige vertaling van dit Titanenschrift. Ik kan nu al nieuwe woorden lezen! Hmm... hier staat: \"Oude Goden... Geketend onder het land.\" Dit is het begin van iets groots.",
  g = { {"opgraven", "to dig up, uncover"}, {"stenen tafel", "stone tablet"}, {"vertaalde", "translated (vertalen)"}, {"breekt", "breaks (afbreken: break off)"}, {"goddelijk", "divine"}, {"profetie", "prophecy"}, {"trotseren", "to brave, defy"}, {"doorzoek", "scour, search (doorzoeken)"}, {"opgravingsplek", "excavation site"}, {"ontbrekende", "missing (ontbreken)"}, {"voorwerpen", "objects, artifacts (voorwerp)"}, {"lastige", "tricky, delicate (lastig)"}, {"Titanenschrift", "Titan script"}, {"geketend", "chained (ketenen)"} },
},

[464] = { en = "War Banners", tier = 2,
  t = "Oorlogsbanieren",
  d = "De orcclan Dragonmaw was aan het einde van de Tweede Oorlog bijna helemaal vernietigd, nadat ze de controle over hun tamme rode draken verloren. De draken waren niet erg blij met hun oude meesters, en ze joegen fel op de Dragonmaws. De weinigen die over waren, vluchtten weg uit Grim Batol, de bergen in ten oosten van Whelgar's Excavation.$B$BNu zijn ze weer sterker geworden, en ze hebben een kamp ten noordoosten van Menethil.$B$BWe willen dat je dat kamp aanvalt. Verzamel hun oorlogsbanieren en breng ze naar mij als bewijs.",
  o = "Breng 8 Dragonmaw War Banners naar Captain Stoutfist.",
  p = "Heb je het kamp van de Dragonmaw aangevallen?",
  c = "Goed gevochten, $N. De Dragonmaws zijn niet meer zo gevaarlijk als toen ze draken hadden, maar het zijn nog steeds felle tegenstanders.$b$bDe Dragonmaws worden geleid door Nek'rosh, de zoon van Nekros. Nekros was jaren geleden het hoofd van de Dragonmaws. Nekros gebruikte sterke magie om de rode draken te temmen, maar toen die magie hem in de steek liet... waren de draken niet blij.$b$bNekros werd gedood, en zijn zoon heeft wraak gezworen op de draken die zijn vader hebben gedood.",
  g = { {"oorlogsbanieren", "war banners (oorlogsbanier)"}, {"vernietigd", "destroyed (vernietigen)"}, {"tamme", "tame (tam)"}, {"joegen", "hunted (jagen)"}, {"fel", "fierce, fiercely"}, {"kamp", "camp, encampment"}, {"bewijs", "proof"}, {"tegenstanders", "opponents (tegenstander)"}, {"temmen", "to tame"}, {"in de steek liet", "failed, let down (in de steek laten)"}, {"gezworen", "sworn, vowed (zweren)"} },
},

