[289] = { en = "The Cursed Crew", tier = 2,
  t = "De vervloekte bemanning",
  d = "<Opgekikkerd gaat Fitzsimmons verder met zijn verhaal...>$B$BIk ben de enige overlevende van de rampzalige Derde Vloot van Kul Tiras, die in het noorden voor de kust is vergaan. Maar ik ben dan wel het enige lid van de vloot dat nog ademt, ik ben niet de enige die nog rondloopt! Want op een van onze schepen was een grote en vreselijke schat verborgen. De griezelige kracht ervan houdt de zielen van mijn broeders gevangen in de rottende rompen van de schepen.$B$BMaar als je een paar van mijn broeders kunt bevrijden, kun je misschien hun vloek breken.",
  o = "Dood 13 Cursed Sailors, 5 Cursed Marines en First Mate Snellig. Breng Snellig's Snuffbox naar First Mate Fitzsimmons in Menethil Harbor.",
  p = "In mijn dromen hoor ik soms het gekreun van mijn gedoemde broeders! Alsjeblieft, beste meneer, bevrijd ze uit hun boeien en laat hun geschreeuw stoppen.",
  c = "Mijn dank, $N. En ook mijn vervloekte broeders zijn je dankbaar.",
  g = { {"bemanning", "crew"}, {"opgekikkerd", "bolstered, perked up (opkikkeren)"}, {"rampzalige", "ill-fated (rampzalig)"}, {"vergaan", "wrecked, perished"}, {"ademt", "breathes (ademen)"}, {"verborgen", "hidden (verbergen)"}, {"griezelige", "eerie (griezelig)"}, {"zielen", "souls (ziel)"}, {"broeders", "brothers, brethren (broeder)"}, {"rottende", "rotting (rotten)"}, {"rompen", "hulls (romp)"}, {"vloek", "curse"}, {"gekreun", "moaning"}, {"boeien", "bonds, chains (boei)"} },
