[296] = { en = "Ormer's Revenge", tier = 2,
  t = "De wraak van Ormer",
  d = "Terwijl jij daar beneden was, zag ik dat een van die beesten anders was dan de rest. Hij was groter en dreigender. Ik wed dat hij de anderen hierheen heeft geleid om het graafwerk te verstoren.$b$bIk vraag je nu om een laatste taak, $N. Zorg dat er gerechtigheid komt voor wat Sarltooth heeft gedaan. En omdat zijn misdaden zo zwaar zijn, betekent gerechtigheid hier de dood! Breng me een van zijn klauwen als bewijs dat hij dood is.",
  o = "Ormer Ironbraid bij de Whelgar Excavation Site wil dat je Sarltooth doodt. Ga terug naar hem met een van zijn klauwen als de taak klaar is.",
  p = "Is Sarltooth dood? Heb je de gevallenen hun eer teruggegeven?",
  c = "Dank je, $N. Wat je hier hebt gedaan, wordt niet vergeten. Veel onschuldige dwergen zijn op deze plek gestorven, terwijl ze gewoon hun werk deden. Door de wraak die jij hebt genomen op die kwaadaardige beesten, denken ze voortaan wel twee keer na voordat ze de onderdanen van King Magni weer aanvallen.",
  g = { {"dreigender", "more menacing (dreigend)"}, {"wed", "bet (wedden)"}, {"graafwerk", "dig, digging work"}, {"verstoren", "to disrupt"}, {"gerechtigheid", "justice"}, {"misdaden", "crimes (misdaad)"}, {"klauwen", "talons, claws (klauw)"}, {"gevallenen", "the fallen"}, {"onschuldige", "innocent (onschuldig)"}, {"kwaadaardige", "evil, malicious (kwaadaardig)"}, {"voortaan", "from now on"}, {"onderdanen", "subjects (onderdaan)"} },
},

[290] = { en = "Lifting the Curse", tier = 2,
  t = "De vloek opheffen",
  d = "Om de vloek te breken en al mijn broeders te bevrijden, moet het... ding... dat op mijn schip verstopt is, worden opgehaald en gereinigd! Ik weet niet wat het was, maar ik weet wel dat het veilig was opgeborgen in de geldkist van het schip. Captain Halyndor had daar de baas over.$B$BIk zie mijn oude kapitein nog steeds in mijn dromen. Ik weet dat hij rondloopt op mijn gedoemde schip, de Intrepid. Haal de sleutel bij hem, en open daarmee de geldkist van de Intrepid.$B$BBreng het vervloekte ding daarna naar de priester Glorin Steelbrow in de stad.",
  o = "Haal de Intrepid Strongbox Key bij Captain Halyndor.$B$BOpen met de sleutel de Intrepid's Locked Strongbox.",
  p = "Deze kist zit stevig op slot.",
  c = "De sleutel is verroest, maar hij past precies in het slot.",
  g = { {"opheffen", "to lift, remove"}, {"verstopt", "hidden, stowed (verstoppen)"}, {"opgehaald", "retrieved (ophalen)"}, {"gereinigd", "cleansed (reinigen)"}, {"opgeborgen", "stored (opbergen)"}, {"geldkist", "strongbox"}, {"de baas", "in charge (de baas zijn over)"}, {"stevig", "securely, firmly"}, {"op slot", "locked"}, {"verroest", "rusted"}, {"precies", "exactly, neatly"} },
},

[292] = { en = "The Eye of Paleth", tier = 2,
  t = "Het Eye of Paleth",
  d = "Als je de kist opent, zie je een zwartgeblakerde bol die klopt met een griezelig licht. Het is de schat waar Fitzsimmons over sprak: een Cursed Eye of Paleth.$B$BBreng het Cursed Eye of Paleth naar de dwergenpriester Glorin Steelbrow in Menethil Harbor. Vraag hem hoe je de vloek van het Eye kunt verwijderen.",
  o = "Breng het Cursed Eye of Paleth naar Glorin Steelbrow.",
  p = "Heeft die dronkaard Fitzsimmons je naar mij gestuurd? Nou, zeg maar tegen hem dat ik geen extra bier heb. Hij moet maar bij iemand anders gaan bedelen!",
  c = "Een Eye of Paleth? Geweldig! Hmm... er is iets mis met dit exemplaar. Heb je het gevonden op een van die scheepswrakken? Nou, dat verklaart het! Maar... ik wist niet dat ze zo'n Eye bij de Derde Vloot hadden...$B$BGeen wonder dat Fitzsimmons zo bang was. Een Cursed Eye of Paleth is geen reden om vrolijk te zijn.",
  g = { {"zwartgeblakerde", "blackened (zwartgeblakerd)"}, {"bol", "orb, sphere"}, {"klopt", "pulses, beats (kloppen)"}, {"dwergenpriester", "dwarven priest"}, {"verwijderen", "to remove"}, {"dronkaard", "drunk, drunkard"}, {"bedelen", "to beg, panhandle"}, {"exemplaar", "specimen, one (of a kind)"}, {"scheepswrakken", "shipwrecks (scheepswrak)"}, {"verklaart", "explains (verklaren)"}, {"geen wonder", "no wonder"} },
},

[293] = { en = "Cleansing the Eye", tier = 2,
  t = "Het Eye reinigen",
  d = "Ik kan de vloek niet van het Eye of Paleth halen. De Eyes zijn gemaakt door menselijke priesters, dus je moet naar Stormwind om iemand te vinden die je kan helpen. Spreek met Archbishop Benedictus. Hij is het hoofd van de Cathedral of Light in Stormwind. Hij kan helpen.$B$BIk hoop het, voor jou.",
  o = "Breng het Cursed Eye of Paleth naar Archbishop Benedictus. Benedictus is in de Cathedral of Light, in de stad Stormwind.",
  p = "Wat is dat voor een bol die je hebt? Hij ziet er... besmeurd uit.",
  c = "Een Eye of Paleth. Maar dit exemplaar heeft veel verdriet gezien... het moet getuige zijn geweest van een vreselijke, vreselijke tragedie.$b$bLaat mij het reinigen, want de Eyes zijn gemaakt om fel te schijnen, en hun krachten kunnen behoorlijk gevaarlijk zijn als ze zo besmet zijn als dit exemplaar.",
  g = { {"reinigen", "to cleanse"}, {"menselijke", "human (menselijk)"}, {"besmeurd", "soiled, smeared"}, {"verdriet", "sorrow"}, {"getuige", "witness"}, {"tragedie", "tragedy"}, {"schijnen", "to shine"}, {"behoorlijk", "quite, fairly"}, {"besmet", "tainted, infected"} },
},

[303] = { en = "The Dark Iron War", tier = 2,
  t = "De oorlog met de Dark Irons",
  d = "Er woedt oorlog, thuis én ver weg. Terwijl machtige dwergensoldaten in verre gebieden hun leven geven voor de Alliance, worden onze eigen landen het slachtoffer van de slechte daden van de Dark Iron Dwarves. Ze hebben de Thandol Span verwoest. Kort daarna viel Dun Modr.$b$bWe willen dat je kracht verzamelt en het front terugduwt. Als je 15 Dark Iron Dwarves, 5 Tunnelers, 5 Saboteurs en 5 Demolitionists kunt doden, komt de reserve misschien op tijd om de opmars af te maken.$b$bSchiet nu op!",
  o = "Motley Garmason bij Dun Modr wil dat je 15 Dark Iron Dwarves, 5 Dark Iron Tunnelers, 5 Dark Iron Saboteurs en 5 Dark Iron Demolitionists doodt.",
  p = "Roggo krijgt geen contact met de reservetroepen. We moeten druk zetten op dat kamp van de Dark Irons, $c. Ga nu terug naar buiten en doe je plicht voor King Magni!",
  c = "Je hebt je bevelen goed uitgevoerd, $C. Je hebt bewezen dat je een dappere soldaat bent en een trouwe dienaar van King Magni, en daarvoor salueer ik voor je! Door de druk die jij op het kamp van de Dark Irons hebt gezet, hebben we nu een kans om ze voorgoed van ons land te verdrijven... als die verdomde reserve maar eens kwam...",
  g = { {"woedt", "rages (woeden)"}, {"verre", "far-off (ver)"}, {"gebieden", "territories, areas (gebied)"}, {"slachtoffer", "victim, prey"}, {"daden", "deeds (daad)"}, {"verwoest", "laid waste, destroyed (verwoesten)"}, {"terugduwt", "pushes back (terugduwen)"}, {"opmars", "advance, drive"}, {"reservetroepen", "reserve forces"}, {"plicht", "duty"}, {"bevelen", "orders (bevel)"}, {"uitgevoerd", "carried out (uitvoeren)"}, {"dienaar", "servant"}, {"salueer", "salute (salueren)"}, {"verdrijven", "to drive off"} },
},

[647] = { en = "MacKreel's Moonshine", tier = 2,
  t = "De Moonshine van MacKreel",
  d = "Ik heb gisteravond flink wat van de ouwe Moonshine gedronken! Longbraid zou me de kop afhakken als hij wist dat ik tijdens mijn wacht ben flauwgevallen.$b$bMijn hoofd doet vreselijk pijn. Het voelde alsof een hele brigade belegeringsmachines over me heen reed, met al dat gedreun.$b$bO jee, kijk eens hoe laat het is! Ik heb Brewmeister Bilger in Southshore beloofd dat ik mijn schuld bij hem zou afbetalen met wat Moonshine.$b$bMaar ik heb nog maar 15 minuten voordat ik te laat ben! Wil je deze partij naar hem brengen? En schiet op!",
  o = "Breng MacKreel's Moonshine naar Brewmeister Bilger in Southshore.",
  p = "Wat is er voor nieuws, $R?",
  c = "Ah, er gaat niets boven de Moonshine van Foggy MacKreel om je op te warmen op een frisse dag! En ik dacht nog dat die kleine rakker weer te laat zou zijn met zijn rekeningen. Bedankt, vriend! Heel erg bedankt!",
  g = { {"flink wat", "quite a bit"}, {"ouwe", "old (informal, oud)"}, {"de kop afhakken", "have my head (chop off the head)"}, {"wacht", "watch, guard duty"}, {"flauwgevallen", "passed out (flauwvallen)"}, {"belegeringsmachines", "siege engines"}, {"gedreun", "rumbling"}, {"schuld", "debt"}, {"afbetalen", "to pay off, repay"}, {"partij", "batch"}, {"er gaat niets boven", "there's nothing like"}, {"rakker", "rascal, little bugger"}, {"rekeningen", "bills (rekening)"} },
},

[465] = { en = "Nek'rosh's Gambit", tier = 2,
  t = "De list van Nek'rosh",
  d = "Terwijl jij tegen de Dragonmaws vocht, ontdekten wij meer van hun plannen.$B$BNek'rosh heeft katapulten gebouwd en wil Menethil belegeren! En door de gevechten in Dun Algaz kunnen er in feite geen versterkingen naar ons komen!$B$BJe moet die katapulten vernietigen. Ze staan in het kamp van de Dragonmaw.$B$BHier, neem dit tondel. Vecht je een weg naar de katapulten en steek ze aan met het tondel.$B$BEn als je dat gedaan hebt, zoek en dood dan Nek'rosh. We moeten dit beest van de Dragonmaw neerhalen... bij zijn nek.",
  o = "Vernietig de katapulten van de Dragonmaw.",
  p = "De eerste katapult staat voor je. Steek je hem in brand?",
  c = "Je legt wat tondel op de katapult en slaat er een vonk op.$B$BEr laaien vlammen op, en het vuur verspreidt zich snel!",
  g = { {"list", "gambit, trick"}, {"katapulten", "catapults (katapult)"}, {"belegeren", "to lay siege to"}, {"in feite", "effectively, in fact"}, {"versterkingen", "reinforcements (versterking)"}, {"tondel", "tinder"}, {"steek", "light (aansteken: set on fire)"}, {"neerhalen", "to cut down, bring down"}, {"in brand", "on fire, aflame"}, {"vonk", "spark"}, {"laaien", "flare (oplaaien: flare up)"}, {"verspreidt", "spreads (verspreiden)"} },
},

[631] = { en = "The Thandol Span", tier = 2,
  t = "De Thandol Span",
  d = "Een enorme explosie bulderde door de heuvels. Het was verschrikkelijk, zeg ik je!$b$bGoede soldaten zijn gestorven toen ze de Thandol Span verdedigden. Longbraid zegt dat we wraak nemen op de Dark Irons voordat dit allemaal voorbij is.$b$bMaar we zitten flink in de problemen, en ik zie nergens versterkingen. Longbraid stuurde Ol' Rustlocke om de oostelijke brug te verkennen. Hij moest kijken of we die konden beveiligen.$b$bDat is dagen geleden. We hebben niet genoeg mensen om hem te zoeken, nu Dun Modr belegerd wordt.$b$bMisschien kun jij hem vinden...",
  o = "Rhag Garmason wil dat je Ol' Rustlocke vindt.",
  c = "Je doorzoekt het kleine lijk van de dwerg. In de helm staat duidelijk een naam gegraveerd: Ebenezer Rustlocke.",
  g = { {"enorme", "tremendous, huge (enorm)"}, {"bulderde", "roared (bulderen)"}, {"verschrikkelijk", "horrible"}, {"verdedigden", "defended (verdedigen)"}, {"flink in de problemen", "in a world of hurt"}, {"oostelijke", "eastern (oostelijk)"}, {"verkennen", "to scout"}, {"beveiligen", "to secure"}, {"belegerd", "besieged (belegeren)"}, {"lijk", "corpse"}, {"gegraveerd", "engraved (graveren)"} },
},

[632] = { en = "The Thandol Span", tier = 2,
  t = "De Thandol Span",
  d = "Het lijkt erop dat de arme Ol' Rustlocke in een hinderlaag van de Dark Irons is gelopen. Je ziet een stuk perkament naast zijn gebalde vuist.$b$bBreng het droevige nieuws naar Rhag Garmason en laat hem zien wat je hebt gevonden.",
  o = "Ga terug naar Rhag Garmason en laat hem het perkament zien dat je bij het lijk van Rustlocke hebt gevonden.",
  p = "Heb je al iets van Ol' Rustlocke gezien, $N?",
  c = "O jee, het nieuws is ernstig....",
  g = { {"het lijkt erop", "it seems"}, {"hinderlaag", "ambush"}, {"perkament", "parchment"}, {"gebalde", "clenched (gebald)"}, {"vuist", "fist"}, {"droevige", "sad, grim (droevig)"} },
},

[633] = { en = "The Thandol Span", tier = 2,
  t = "De Thandol Span",
  d = "O hemel, nee! Arme Rustlocke. Wat een tragedie.$b$bZijn dood mag niet voor niets zijn geweest. Dit perkament dat je hebt gevonden laat zien dat Kam Deepfury, het brein achter de eerste aanval, een voorraad explosieven heeft laten verstoppen, vlak aan de overkant van de Thandol Span, in Arathi Highlands.$b$bAls die explosieven bij de brug komen, wordt onze belangrijkste aanvoerlijn naar het noorden afgesneden! De voorraad moet vernietigd worden, $n! Kom terug naar mij als je missie klaar is.$b$bJij bent onze enige hoop.",
  o = "Vernietig de voorraad explosieven.",
  p = "De voorraad explosieven moet vernietigd worden!",
  c = "De overgebleven brug is gered! Je hebt King Magni en het volk van Khaz Modan een grote dienst bewezen.$B$BAls we het nu maar lang genoeg kunnen volhouden tot de versterkingen komen...",
  o1 = "Cache of Explosives vernietigd",
  g = { {"hemel", "heavens"}, {"voor niets", "in vain"}, {"brein", "mastermind, brain"}, {"voorraad", "cache, supply"}, {"explosieven", "explosives (explosief)"}, {"overkant", "other side"}, {"aanvoerlijn", "supply line"}, {"afgesneden", "cut off, severed (afsnijden)"}, {"overgebleven", "remaining"}, {"dienst bewezen", "done a service (een dienst bewijzen)"}, {"volhouden", "to hold out"} },
},

[634] = { en = "Plea To The Alliance", tier = 2,
  t = "Een dringend verzoek aan de Alliance",
  d = "Ik vraag je nog één kleine gunst, $c. We wachten op de reserves van Ironforge. Maar Roggo weet van een kamp van de Alliance in het noorden, in Arathi Highlands, bij Refuge Pointe.$b$bReis daarheen en zoek Captain Nials op. Vraag de goede kapitein of de Alliance een paar soldaten kan missen om ons te helpen Dun Modr en de Thandol Span terug te veroveren.",
  o = "Zoek Captain Nials op bij Refuge Pointe.",
  c = "Mijn medeleven gaat uit naar Longbraid en zijn dappere soldaten. Het nieuws over de ramp bij de Thandol Span en de val van Dun Modr ligt zwaar op mijn hart.$b$bMaar Stromgarde is gevallen! Daarom zijn we hier bij Refuge Pointe. We moeten onze eigen grote stad terugveroveren.$b$bEer en plicht eisen dat we de Highlands niet verlaten tot de machtige banier van de koning weer boven Stromgarde wappert. Ik zal Longbraid laten weten dat hij er alleen voor staat...",
  g = { {"dringend", "urgent"}, {"verzoek", "request, plea"}, {"gunst", "favour"}, {"missen", "to spare"}, {"terug te veroveren", "to reclaim (terugveroveren)"}, {"medeleven", "condolences, sympathy"}, {"ramp", "disaster, tragedy"}, {"eer", "honour"}, {"eisen", "require, demand (eisen)"}, {"banier", "banner"}, {"wappert", "flies, waves (wapperen)"}, {"er alleen voor staat", "is on his own (er alleen voor staan)"} },
},

[474] = { en = "Defeat Nek'rosh", tier = 2,
  t = "Versla Nek'rosh",
  d = "Nu de katapulten verbrand zijn, moet je Chieftain Nek'rosh zoeken en doden.",
  o = "Dood Chieftain Nek'rosh.$B$BBreng Nek'rosh's Head naar Captain Stoutfist.",
  p = "Heb je Nek'rosh gedood?",
  c = "Dapper gedaan, $N. Je hebt de orcclan Dragonmaw een zware klap gegeven. Misschien komen ze er nooit meer bovenop. En door de vernietiging van die katapulten is Menethil Harbor veilig.$B$BJe bent een $R van verdienste, en het koninkrijk Ironforge beloont wie het goed dient.",
  g = { {"versla", "defeat (verslaan)"}, {"verbrand", "burned (verbranden)"}, {"klap", "blow"}, {"bovenop", "on top (er bovenop komen: to recover)"}, {"vernietiging", "destruction"}, {"verdienste", "merit"}, {"koninkrijk", "kingdom"}, {"beloont", "rewards (belonen)"}, {"dient", "serves (dienen)"} },
},

[304] = { en = "A Grim Task", tier = 2,
  t = "Een grimmige taak",
  d = "Veel van mijn soldaten zijn gestorven in de slag om Dun Modr. Mijn eigen broer kwam om toen de West Bridge over de Thandol Span werd verwoest. Ja, de Dark Iron Dwarves zijn een duivels ras. Volgens wat Roggo te weten kwam, is de leider van deze bende boeven in de Wetlands een heksenmeester die Balgaras the Foul heet. Maar hij is nogal een lafaard. Hij laat zijn soldaten het werk voor hem doen, maar zelf blijft hij onvindbaar en gaat hij gevaar uit de weg.$b$bAls je dat laffe tuig kunt vinden, dood hem en breng me zijn oor. Ik zal je belonen, $c.",
  o = "Dood Balgaras the Foul en breng zijn oor naar Longbraid the Grim buiten Dun Modr.",
  p = "Heb je Balgaras the Foul al kunnen vinden, $C? Hij ontloopt ons al een hele tijd.",
  c = "Balgaras the Foul is eindelijk dood. Zijn dood brengt de vele onschuldige dwergen die zonder reden door zijn hand zijn gestorven niet terug. Maar het helpt wel om de overlevenden weer wat gemoedsrust te geven. Nu Balgaras dood is, moet het tuig van de Dark Irons dat nog over is makkelijk genoeg aan te pakken zijn. Nu moeten we ze uitroeien voordat er een nieuwe leider naar deze streek wordt gestuurd.$B$BJe hebt het goed gedaan, $C.",
  g = { {"grimmige", "grim (grimmig)"}, {"slag", "battle"}, {"kwam om", "perished (omkomen)"}, {"duivels", "devilish"}, {"ras", "breed, race"}, {"bende", "band, gang"}, {"heksenmeester", "warlock"}, {"lafaard", "coward"}, {"onvindbaar", "elusive, impossible to find"}, {"laffe", "spineless, cowardly (laf)"}, {"tuig", "scum"}, {"ontloopt", "evades (ontlopen)"}, {"gemoedsrust", "peace of mind"}, {"uitroeien", "to wipe out"}, {"streek", "region, parts"} },
},

[1302] = { en = "James Hyal", tier = 2,
  t = "James Hyal",
  d = "Mijn broer James ging met Lady Proudmoore mee over de zee. Het laatste wat ik hoorde, was dat de gevechten daar wat tot rust waren gekomen en dat James ergens op dat continent een herberg begon. Waar hij ook is, ik weet zeker dat zijn zaak goed loopt. Hij was een verdraaid goede kok.$b$bIk heb al een tijdje niets van hem gehoord. Hij heeft het vast te druk met zijn herberg, wed ik. Maar de klerk in Theramore kan je waarschijnlijk wel vertellen waar hij is.",
  o = "Spreek met Clerk Lendry in Theramore.",
  c = "James Hyal, James Hyal... Waarom klinkt die naam zo bekend?$B$BNatuurlijk! Het incident in de Shady Rest Inn. Als je iets weet over wat daar is gebeurd, raad ik je dringend aan om er met Captain Vimes over te praten. Hij leidt het onderzoek.",
  g = { {"tot rust gekomen", "settled down (tot rust komen)"}, {"continent", "continent"}, {"herberg", "inn"}, {"zijn zaak", "his business"}, {"verdraaid", "damn (mild curse)"}, {"vast", "surely, probably"}, {"klerk", "clerk"}, {"bekend", "familiar"}, {"raad", "advise (aanraden)"}, {"onderzoek", "investigation"} },
},

})

